export const title = "How to Choose a Laundry Hamper for a Narrow Bedroom";
export const metaTitle = "How to Choose a Laundry Hamper for a Narrow";
export const metaDescription = "Choose a narrow-bedroom laundry hamper by its loaded footprint, liner removal, carry route, and drying routine. A research-based guide from DeskFinds.";
